lesson.content:
// Finding two elements by their ids
let btn = document.getElementById('action-btn');
let output = document.getElementById('output');
// btn is the button element, output is where we'll show text

// The basic shape:
// element.addEventListener('event-name', functionToRun);

// Example:
btn.addEventListener('click', someFunction);
// When btn is clicked, someFunction runs

// You can use a function you already defined:
function handleClick() {
  console.log('Button was clicked!');
}
btn.addEventListener('click', handleClick);
// handleClick is the callback — it runs when the button is clicked

// These two do the same thing:

// Old way:
function sayHi() {
  console.log('Hi!');
}

// Arrow function (newer, shorter):
() => {
  console.log('Hi!');
}

// Using an arrow function with addEventListener:
btn.addEventListener('click', () => {
  console.log('Clicked!');
});
// The arrow function runs when someone clicks btn

// Get an element and change its text
let output = document.getElementById('output');
output.textContent = 'Clicked!';
// Now the element shows "Clicked!" instead of whatever it had before

// The pattern you'll write:
function setupButton() {
  let btn = document.getElementById('action-btn');
  let output = document.getElementById('output');

  btn.addEventListener('click', () => {
    output.textContent = 'Clicked!';
  });
}

// After setupButton() runs, clicking #action-btn
// will make #output show "Clicked!"

