  // Inside, title is 'Hello' and body is 'World'
  // if called as: createCard('Hello', 'World')
}

// Parameters work like variables that are automatically created
// with the values passed when the function is called

let heading = document.createElement('h3');
heading.textContent = 'My Title';
// Now heading is: <h3>My Title</h3>

let card = document.createElement('div');
let heading = document.createElement('h3');
heading.textContent = 'Hello';

card.appendChild(heading);
// Now card contains: <div><h3>Hello</h3></div>
// heading is now a child of card

function createCard(title, body) {
  let card = document.createElement('div');
  // ... build it up ...
  return card; // Send the finished card back
}

let myCard = createCard('Hi', 'There');
// myCard now holds the card element we built

// The full pattern:
function createCard(title, body) {
  let card = document.createElement('div');
  card.classList.add('card');

  let heading = document.createElement('h3');
  heading.textContent = title;

  let para = document.createElement('p');
  para.textContent = body;

  card.appendChild(heading);
  card.appendChild(para);

  return card;
}

// createCard('My Title', 'My Body') returns:
// <div class="card">
//   <h3>My Title</h3>
//   <p>My Body</p>
// </div>

